      "estimated_cpu_cost": "$850–1,100"
    }
  },
  "target_venues": [
    "ICLR 2027",
    "COLM 2027"
  ],
  "level": "strong",
  "key_references": [
    "ReForm: Reflective Autoformalization with PBSO (ICLR 2026)",
